package com.yeyamo_mobile.api.discovery_service.domain.model;import java.time.Instant;import java.util.UUID;
public record DiscoveryDocument(UUID id,String sourceId,DiscoveryType type,String title,String description,String categoryCode,String regionCode,String city,Double latitude,Double longitude,String authorId,double trendScore,boolean active,Instant publishedAt,Instant updatedAt){public DiscoveryDocument{if(id==null)throw new IllegalArgumentException("id is required");if(sourceId==null||sourceId.isBlank())throw new IllegalArgumentException("sourceId is required");if(type==null)throw new IllegalArgumentException("type is required");if(title==null||title.isBlank())throw new IllegalArgumentException("title is required");if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("latitude and longitude must be provided together");if(latitude!=null&&(latitude < -90||latitude > 90||longitude < -180||longitude > 180))throw new IllegalArgumentException("Invalid coordinates");}}
